import static org.mockito.Mockito.when;

public class MakeDeclaredNamesUnique_visit_TriageGen2Test {

  private Compiler compiler;
  private NodeTraversal nodeTraversal;
  private MakeDeclaredNamesUnique makeDeclaredNamesUnique;
  private Stack<Renamer> mockStack;
  private Renamer mockRenamer;

  // Mocking Renamer as it is an internal dependency used via nameStack
  public interface Renamer {
    boolean stripConstIfReplaced();
  }

  @Before
  public void setUp() {
    compiler = makeCompiler();
    nodeTraversal = mock(NodeTraversal.class);
    when(nodeTraversal.getCompiler()).thenReturn(compiler);

    makeDeclaredNamesUnique = new MakeDeclaredNamesUnique() {
      // We override or use reflection if nameStack is private, 
      // but assuming we can control the internal state for testing.
      // Since the provided code uses nameStack.peek(), we need to inject it.
      // For the purpose of this test, we assume access to the protected/package-private field.
      public Stack<Renamer> nameStack = new Stack<>();
    };

    mockStack = new Stack<>();
    mockRenamer = mock(Renamer.class);
    mockStack.push(mockRenamer);

    // Using reflection to inject the stack into the actual instance if it's private
    try {
      java.lang.reflect.Field field = MakeDeclaredNamesUnique.class.getDeclaredField("nameStack");
      field.setAccessible(true);
      field.set(makeDeclaredNamesUnique, mockStack);
    } catch (Exception e) {
      throw new RuntimeException(e);
    }
  }

  @Test
  public void testVisit_Name_Replaced_And_Stripped() {
    Node n = new Node(Token.NAME, "oldName");
    n.setProperty(Node.IS_CONSTANT_NAME, true);

    // Mocking getReplacementName behavior via a spy or partial mock if possible.
    // Since we can't easily mock the internal method getReplacementName without spying,
    // we assume the class is designed such that we can test the logic.
    MakeDeclaredNamesUnique spyVisitor = Mockito.spy(makeDeclaredNamesUnique);
    doReturn("newName").when(spyVisitor).getReplacementName("oldName");
    when(mockRenamer.stripConstIfReplaced()).thenReturn(true);

    spyVisitor.visit(nodeTraversal, n, null);

    assertEquals("newName", n.getString());
    assertEquals(false, n.hasProp(Node.IS_CONSTANT_NAME));
    // Verify compiler reported change
    // In a real scenario, we'd check the internal state of the compiler's change tracking
  }

  @Test
  public void testVisit_Name_Replaced_NotStripped() {
    Node n = new Node(Token.NAME, "oldName");
    n.setProperty(Node.IS_CONSTANT_NAME, true);

    MakeDeclaredNamesUnique spyVisitor = Mockito.spy(makeDeclaredNamesUnique);
    doReturn("newName").when(spyVisitor).getReplacementName("oldName");
    when(mockRenamer.stripConstIfReplaced()).thenReturn(false);

    spyVisitor.visit(nodeTraversal, n, null);

    assertEquals("newName", n.getString());
    assertEquals(true, n.hasProp(Node.IS_CONSTANT_NAME));
  }

  @Test
  public void testVisit_Name_NotReplaced() {
    Node n = new Node(Token.NAME, "oldName");

    MakeDeclaredNamesUnique spyVisitor = Mockito.spy(makeDeclaredNamesUnique);
    doReturn(null).when(spyVisitor).getReplacementName("oldName");

    spyVisitor.visit(nodeTraversal, n, null);

    assertEquals("oldName", n.getString());
  }

  @Test
  public void testVisit_Function_PopsStack() {
    Node n = new Node(Token.FUNCTION);

    makeDeclaredNamesUnique.visit(nodeTraversal, n, null);

    assertEquals(0, mockStack.size());
  }

  @Test
  public void testVisit_Catch_PopsStack() {
    Node n = new Node(Token.CATCH);

    makeDeclaredNamesUnique.visit(nodeTraversal, n, null);

    assertEquals(0, mockStack.size());
  }

  @Test
  public void testVisit_OtherToken_DoesNothing() {
    Node n = new Node(Token.COMMA);
    int initialStackSize = mockStack.size();

    makeDeclaredNamesUnique.visit(nodeTraversal, n, null);

    assertEquals(initialStackSize, mockStack.size());
    assertEquals(Token.COMMA, n.getType());
  }
}
